#!/usr/bin/env node
// Checks a Toko install: the generated files, how they're imported, variables and surfaces the
// code uses that nothing defines, hard-coded leftovers, the AGENTS.md section, and, with a
// toko.json, that the generated files and spec still match its lock. Read-only.
// Prints JSON to stdout; exits 0 when every check passes, 1 when one fails. Node 18+.

import { createHash } from "node:crypto"
import { existsSync, readFileSync, statSync } from "node:fs"
import { dirname, join, relative, resolve } from "node:path"
import { pathToFileURL } from "node:url"
import { KEEP, inventory, isTokoFile, sourceFiles } from "./inventory.mjs"

const HELP = `Usage: node check.mjs [dir]

Checks the Toko install in [dir] (default: the current folder):
  files       tokens.css (and tailwind.css with Tailwind v4) generated by Toko are present, once
  imports     the Toko files are imported exactly once
  variables   every var(--…) the code uses is declared somewhere (catches renamed or removed tokens)
  surfaces    every data-surface="…" the code uses exists in tokens.css (catches renamed surfaces)
  leftovers   hard-coded colors, shadows and font sizes still in the code (details: inventory.mjs);
              lines marked toko-keep are kept on purpose and don't count
  rules       AGENTS.md or CLAUDE.md has one Toko section; CLAUDE.md points to AGENTS.md if both exist
  sync        only with a toko.json: the generated files and the spec match its lock (catches hand edits
              and spec changes that weren't pushed)

Prints {ok, checks: {name: {ok, …details}}}. Exit code 0 = all passed, 1 = something to fix, 2 = bad arguments.`

const START = "<!-- toko:start -->"
const END = "<!-- toko:end -->"
const LIST = 50
// Variables that libraries declare at runtime or in node_modules, which the scan can't see.
const LIBRARY = /^--(tw|radix|framer|motion|sb|next|vaul|sonner|cmdk|mantine|chakra|mui|rdp|rt|swiper|fa)-/
// Tailwind v4's own theme, minus what Toko's tailwind.css replaces (colors, text sizes, shadows, fonts).
const TAILWIND_THEME = /^--(spacing|radius|breakpoint|container|ease|animate|blur|perspective|aspect|inset-shadow|drop-shadow|text-shadow|tracking|leading|default)(-|$)/

const read = path => {
    try {
        return statSync(path).size > 1_000_000 ? "" : readFileSync(path, "utf8")
    } catch {
        return ""
    }
}

/** Custom properties a CSS text or a style object declares: `--x:` and `"--x":`. */
const declared = text => [...text.matchAll(/(?<![\w-])(--[\w-]+)["']?\s*:/g)].map(m => m[1])
/** Custom properties used through var() or Tailwind v4's `bg-(--x)`, outside lines marked toko-keep. */
const used = text =>
    [...text.matchAll(/(?:var\(\s*|-\()(--[\w-]+)/g)]
        .map(m => ({ name: m[1], index: m.index }))
        .filter(u => !KEEP.test(text.slice(text.lastIndexOf("\n", u.index) + 1, text.indexOf("\n", u.index) >>> 0)))
const lineAt = (text, index) => text.slice(0, index).split("\n").length

// ─── toko.json ──────────────────────────────────────────────────────────────
// The Toko CLI writes toko.json's lock with these, so the CLI and this script agree on what
// "unchanged" means. Exported for the CLI.

/**
 * "sha256-<base64>" of a text, as toko.json's lock stores it. Windows line endings (CRLF) count
 * as LF, so a checkout with git's autocrlf doesn't look edited by hand.
 */
export const hash = text => `sha256-${createHash("sha256").update(text.replace(/\r\n/g, "\n"), "utf8").digest("base64")}`

/** JSON with object keys sorted and no spaces, so the same spec always hashes the same. */
export const canonicalJson = value =>
    Array.isArray(value)
        ? `[${value.map(v => canonicalJson(v === undefined ? null : v)).join(",")}]`
        : value !== null && typeof value === "object"
          ? `{${Object.keys(value)
                .filter(k => value[k] !== undefined)
                .sort()
                .map(k => `${JSON.stringify(k)}:${canonicalJson(value[k])}`)
                .join(",")}}`
          : JSON.stringify(value)

/** The lock's specHash for a spec. */
export const specHash = spec => hash(canonicalJson(spec))

const CLI = "npx @layoutinc/toko"

/** The sync check, or null without a toko.json. */
export function checkSync(root) {
    const path = join(root, "toko.json")
    if (!existsSync(path)) return null
    let config
    try {
        config = JSON.parse(readFileSync(path, "utf8"))
    } catch (e) {
        return { ok: false, fix: `toko.json isn't valid JSON (${e.message}). Fix it, or run ${CLI} init again.` }
    }
    const linked = typeof config.palette === "string" && config.palette.length > 0
    const lock = config.lock
    if (!lock || typeof lock !== "object" || !lock.files) {
        return { ok: false, palette: config.palette ?? null, fix: `toko.json has no lock yet. Run ${CLI} ${linked ? "pull" : "build"} to write the files.` }
    }
    const out = typeof config.out === "string" ? config.out : ""
    const missing = []
    const edited = []
    for (const [file, expected] of Object.entries(lock.files)) {
        // Paths are relative to the project root; older locks may list them relative to out.
        const full = [join(root, file), join(root, out, file)].find(p => existsSync(p))
        if (!full) missing.push(file)
        else if (hash(readFileSync(full, "utf8")) !== expected) edited.push(file)
    }
    const specChanged = config.spec !== undefined && lock.specHash !== undefined && specHash(config.spec) !== lock.specHash
    const fixes = [
        missing.length > 0 && `Generated files are missing: run ${CLI} ${linked ? "pull" : "build"}.`,
        edited.length > 0 &&
            `Generated files were edited by hand. Move the edit into the palette (${linked ? `in Toko, or with ${CLI} set` : "toko.json's spec"}), then run ${CLI} ${linked ? "pull --force" : "build"}.`,
        specChanged &&
            (linked
                ? `toko.json's spec changed since the last pull: run ${CLI} push -m "<why>" to save it in Toko and update the files.`
                : `toko.json's spec changed since the files were made: run ${CLI} build.`),
    ].filter(Boolean)
    return {
        ok: fixes.length === 0,
        palette: config.palette ?? null,
        revision: lock.revision ?? null,
        missing,
        edited,
        specChanged,
        ...(fixes.length > 0 && { fix: fixes.join(" ") }),
    }
}

export function check(root) {
    const files = sourceFiles(root).map(path => ({ path, rel: relative(root, path), text: read(path) }))
    const toko = files.filter(f => isTokoFile(f.text))
    const tokens = toko.filter(f => f.text.includes("@layer tokens"))
    const tailwind = toko.filter(f => f.text.includes("@theme inline"))
    const project = files.filter(f => !isTokoFile(f.text))
    const checks = {}

    // Files
    const usesTailwind4 = project.some(f => /@import\s+["']tailwindcss["']/.test(f.text)) || tailwind.length > 0
    checks.files = {
        ok: tokens.length === 1 && (!usesTailwind4 || tailwind.length === 1),
        tokens: tokens.map(f => f.rel),
        tailwind: tailwind.map(f => f.rel),
        ...(tokens.length === 0 && { fix: "Add tokens.css from Toko's Export page. Search for 'Generated by Toko' to find it once added." }),
        ...(tokens.length > 1 && { fix: "Keep one copy of tokens.css and delete the others." }),
        ...(usesTailwind4 && tailwind.length === 0 && { fix: "This project uses Tailwind v4: add tailwind.css from Toko next to tokens.css." }),
    }

    // Imports: tailwind.css imports tokens.css itself, so either route counts, but only one.
    // Each import is resolved, so a project file that happens to be called tailwind.css doesn't count.
    const importsOf = targets =>
        project.flatMap(f =>
            [...f.text.matchAll(/(?:@import\s+(?:url\(\s*)?|import\s+|require\(\s*|href\s*=\s*)["']?([^"'\s)?;]+\.css)/g)]
                .filter(m => {
                    // Relative, root-relative, or through an alias like @/ or ~/ (usually the root or src/).
                    const aliased = m[1].replace(/^(?:@|~|\$lib|\$)\//, "")
                    return targets.some(
                        t =>
                            t.path === resolve(dirname(f.path), m[1]) ||
                            (m[1].startsWith("/") && t.path.endsWith(m[1])) ||
                            t.path === resolve(root, aliased) ||
                            t.path === resolve(root, "src", aliased),
                    )
                })
                .map(m => `${f.rel}:${lineAt(f.text, m.index)}`),
        )
    const tokenImports = importsOf(tokens)
    const tailwindImports = importsOf(tailwind)
    const routes = tokenImports.length + tailwindImports.length
    checks.imports = {
        ok: routes === 1,
        tokens: tokenImports,
        tailwind: tailwindImports,
        ...(routes === 0 && { fix: "Import the Toko files once from the global stylesheet or the app's entry." }),
        ...(routes > 1 && { fix: "Import the Toko files from one place only; with Tailwind v4, import tailwind.css and not tokens.css." }),
        ...(tokenImports.length > 0 && tailwindImports.length > 0 && { note: "tailwind.css already imports tokens.css." }),
    }

    // Variables: every var(--x) in the project is declared by Toko, the project or Tailwind's theme.
    const names = new Set(files.flatMap(f => declared(f.text)))
    for (const f of tailwind) for (const name of declared(f.text)) names.add(name)
    const unknown = project.flatMap(f =>
        used(f.text)
            .filter(u => !names.has(u.name) && !LIBRARY.test(u.name) && !(usesTailwind4 && TAILWIND_THEME.test(u.name)))
            .map(u => `${f.rel}:${lineAt(f.text, u.index)} ${u.name}`),
    )
    checks.variables = {
        ok: unknown.length === 0,
        unknown: unknown.slice(0, LIST),
        ...(unknown.length > LIST && { more: unknown.length - LIST }),
        ...(unknown.length > 0 && { fix: "These variables aren't declared anywhere. If a Toko token was renamed or removed, switch to its replacement from the AGENTS.md section." }),
    }

    // Surfaces: data-surface values in the code exist in tokens.css.
    const surfaces = new Set(tokens.flatMap(f => [...f.text.matchAll(/\[data-surface="([^"]+)"\]/g)].map(m => m[1])))
    const badSurfaces = project.flatMap(f =>
        // Literal values, and the ones inside an expression: data-surface={selected ? "selected" : undefined}.
        [...f.text.matchAll(/data-surface\s*=\s*(?:["'`]([\w-]+)["'`]|\{([^}]*)\})/g)]
            .flatMap(m => (m[1] ? [{ name: m[1], index: m.index }] : [...m[2].matchAll(/["'`]([\w-]+)["'`]/g)].map(v => ({ name: v[1], index: m.index }))))
            .filter(v => tokens.length > 0 && !surfaces.has(v.name))
            .map(v => `${f.rel}:${lineAt(f.text, v.index)} ${v.name}`),
    )
    checks.surfaces = {
        ok: badSurfaces.length === 0,
        defined: [...surfaces],
        unknown: badSurfaces.slice(0, LIST),
        ...(badSurfaces.length > 0 && { fix: "These surfaces aren't in tokens.css; they were probably renamed in Toko. Use a name from 'defined'." }),
    }

    // Leftovers
    const inv = inventory(root, 0)
    checks.leftovers = {
        ok: inv.total === 0,
        total: inv.total,
        byKind: inv.byKind,
        ...(inv.total > 0 && { fix: "Run inventory.mjs for the list. Replace each by purpose, or list the ones you keep (images, charts, brand) in the report." }),
    }

    // Rules
    const agents = read(join(root, "AGENTS.md"))
    const claude = read(join(root, "CLAUDE.md"))
    const sections = (agents.split(START).length - 1) + (claude.split(START).length - 1)
    const closed = (agents.split(END).length - 1) + (claude.split(END).length - 1)
    const pointer = !existsSync(join(root, "CLAUDE.md")) || !agents.includes(START) || /(^|\s)@AGENTS\.md(?!\w|\.\w)/.test(claude)
    const placeholder = [agents, claude].some(t => t.includes(START) && t.slice(t.indexOf(START)).includes("<folder>"))
    checks.rules = {
        ok: sections === 1 && closed === 1 && pointer && !placeholder,
        file: agents.includes(START) ? "AGENTS.md" : claude.includes(START) ? "CLAUDE.md" : null,
        ...(sections === 0 && { fix: "Add the Toko section, between <!-- toko:start --> and <!-- toko:end -->, to AGENTS.md." }),
        ...(sections > 1 && { fix: "There's more than one Toko section. Keep one." }),
        ...(sections === 1 && closed !== 1 && { fix: "The Toko section is missing its <!-- toko:end --> marker." }),
        ...(!pointer && { fix: "Add a line '@AGENTS.md' to CLAUDE.md so Claude Code reads the Toko section." }),
        ...(placeholder && { fix: "Replace <folder> in the Toko section with the real path to the Toko files." }),
    }

    const sync = checkSync(root)
    if (sync) checks.sync = sync

    return { ok: Object.values(checks).every(c => c.ok), root, checks }
}

function main(argv) {
    if (argv.includes("--help") || argv.includes("-h")) {
        console.log(HELP)
        return 0
    }
    const dir = argv.find(a => !a.startsWith("-")) ?? "."
    const root = resolve(dir)
    try {
        if (!statSync(root).isDirectory()) throw new Error()
    } catch {
        console.error(`Not a folder: ${dir}. Pass the project folder, e.g. node check.mjs .`)
        return 2
    }
    const result = check(root)
    console.log(JSON.stringify(result, null, 2))
    return result.ok ? 0 : 1
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
    process.exitCode = main(process.argv.slice(2))
}
